/**
 * Wedding functions
 * ------------------------------------------------------------------
 * Each card on the invitation is rendered from one entry below, and
 * each entry owns its own music clip (`audioSrc`). Drop new files into
 * `public/audio/` (or point at an authorised URL) and update the path.
 *
 * Nothing here is Bollywood / copyrighted material — the shipped clips
 * are simple original instrumentals generated by
 * `npm run generate:audio` (see scripts/generate-audio.mjs).
 */

export type EventDecor = "marigold" | "mehendi" | "sparkle" | "royal";
export type EventIcon = "sun" | "flower" | "music" | "crown";

export interface WeddingEvent {
  id: string;
  /** Card heading, e.g. "Haldi". */
  title: string;
  /** Formal sub-heading, e.g. "Haldi Ceremony". */
  subtitle: string;
  tagline: string;
  dateLabel: string;
  timeLabel: string;
  /** ISO 8601 with offset — used for ordering and "add to calendar" links. */
  isoDate: string;
  venue: string;
  description: string;
  dressCode: string;
  /** Colour story of this function, shown as swatches on the card. */
  colorStory: string;
  palette: string[];
  colors: {
    accent: string;
    accentSoft: string;
    accentDeep: string;
    glow: string;
  };
  decor: EventDecor;
  icon: EventIcon;
  image: string;
  /** Individual music clip for this function. */
  audioSrc: string;
  musicTitle: string;
  musicArtist: string;
}

const eventImage = (prompt: string): string =>
  `https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=${encodeURIComponent(
    prompt,
  )}&image_size=landscape_4_3`;

